'use strict';
(() => {
  const M=window.VoyzBudget,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=v=>v===null?'Не задано':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(v);
  let current=M.seed(),revision=0,account=null,client=null,list=[],dirty=false,blocked=false,saving=false,change=0,timer,ready=false;
  const key=()=> 'voyz-budget-draft.v1.'+(account||'guest');
  function status(text){$('#save-status').textContent=text;}
  function notice(text){$('#notice').textContent=text;}
  function cache(){try{localStorage.setItem(key(),JSON.stringify({document:current,revision,dirty}));}catch{notice('Не удалось записать аварийный черновик. Скачайте JSON-бэкап.');}}
  function restoreCache(){try{const c=JSON.parse(localStorage.getItem(key()));if(c){current=M.validate(c.document);revision=Number.isSafeInteger(c.revision)?c.revision:0;dirty=!!c.dirty;return true;}}catch{}return false;}
  function changed(){dirty=true;change++;cache();status(account?'Есть правки · сохраняем…':'Черновик · войдите для онлайн-сохранения');clearTimeout(timer);if(account&&!blocked)timer=setTimeout(save,900);}
  const input=(scope,id,field,value,label,type='number',extra='')=>`<label>${esc(label)}<input data-scope="${scope}" data-id="${id}" data-field="${field}" aria-label="${esc(label)}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" max="10000000000" step="any"':''} ${extra}></label>`;
  const options=(vals,value)=>vals.map(([k,t])=>`<option value="${k}" ${k===value?'selected':''}>${t}</option>`).join('');
  const currency=(scope,r,field='currency')=>`<select class="currency" data-scope="${scope}" data-id="${r.id}" data-field="${field}" aria-label="Валюта ${field==='fuelCurrency'?'бензина ':''}${esc(r.name)}">${options([...new Set([current.settings.currency,...Object.keys(current.settings.rates),r[field]])].map(c=>[c,c]),r[field])}</select>`;
  function settings(){const s=current.settings;$('#settings').innerHTML=[['guests','Гостей (плательщиков)'],['guides','Гидов / водителей'],['days','Дней тура'],['nights','Ночей'],['salePrice','Цена продажи / гость, '+s.currency],['received','Получено от группы, '+s.currency]].map(([f,l])=>input('settings','',f,s[f],l)).join('')+input('settings','','currency',s.currency,'Валюта учёта (3 буквы)','text','maxlength="3"')+`<label>Статус проекта<select data-scope="settings" data-id="" data-field="stage" aria-label="Статус проекта">${options([['planning','Планируем'],['active','В поездке'],['completed','Завершён'],['archived','Архив (не в сводке)']],s.stage)}</select></label>`;$('#rates').innerHTML=Object.entries(s.rates).filter(([code])=>code!==s.currency).map(([code,rate])=>input('rates','',code,rate,'1 '+code+' в '+s.currency)).join('');$('#auto-cars').checked=s.autoCars;}
  function lines(){$('#lines').innerHTML=current.lines.map(r=>`<tr data-row="${r.id}"><td><input data-scope="lines" data-id="${r.id}" data-field="name" aria-label="Название статьи" value="${esc(r.name)}" maxlength="500"><input class="category" data-scope="lines" data-id="${r.id}" data-field="category" aria-label="Категория" value="${esc(r.category)}" maxlength="100"><textarea data-scope="lines" data-id="${r.id}" data-field="note" aria-label="Заметка к статье" maxlength="5000">${esc(r.note)}</textarea></td><td><select data-scope="lines" data-id="${r.id}" data-field="basis" aria-label="На кого считать">${options([['guests','Гости'],['all','Все + гиды'],['guides','Только гиды'],['fixed','Фикс. количество']],r.basis)}</select><label class="extra">Доп. по той же цене<input data-scope="lines" data-id="${r.id}" data-field="extra" aria-label="Дополнительные участники / кони" type="number" min="0" step="1" value="${r.extra??0}"></label><small data-quantity="${r.id}"></small></td><td><input data-scope="lines" data-id="${r.id}" data-field="units" aria-label="Количество единиц" type="number" min="0" step="any" value="${esc(r.unitsMode==='days'?current.settings.days:r.unitsMode==='nights'?current.settings.nights:r.units)}" ${r.unitsMode!=='fixed'?'disabled':''}><select data-scope="lines" data-id="${r.id}" data-field="unitsMode" aria-label="Как считать единицы">${options([['fixed','Вручную'],['days','Дней тура'],['nights','Ночей']],r.unitsMode||'fixed')}</select></td><td><input data-scope="lines" data-id="${r.id}" data-field="price" aria-label="Цена за единицу" type="number" min="0" step="any" value="${esc(r.price)}">${currency('lines',r)}</td><td data-plan="${r.id}"></td><td><input data-scope="lines" data-id="${r.id}" data-field="actual" aria-label="Факт всего в валюте учёта" type="number" min="0" step="any" value="${esc(r.actual)}" placeholder="Не внесён"><label class="close-check"><input type="checkbox" data-scope="lines" data-id="${r.id}" data-field="closed" aria-label="Статья закрыта" ${r.closed?'checked':''}> Всё оплачено</label></td><td data-delta="${r.id}"></td><td><button class="danger" data-remove-line="${r.id}" aria-label="Удалить статью ${esc(r.name)}">×</button></td></tr>`).join('');}
  function vehicles(){const labels=[['count','Количество авто'],['days','Суток аренды'],['rent','Аренда / авто / сутки'],['km','Пробег / авто, км'],['consumption','Расход, л / 100 км'],['fuelPrice','Цена бензина / л'],['actualRent','Факт аренды, '+current.settings.currency],['actualFuel','Факт бензина, '+current.settings.currency]];$('#vehicles').innerHTML=current.vehicles.map(v=>`<div class="vehicle"><div class="vehicle-head"><input data-scope="vehicles" data-id="${v.id}" data-field="name" aria-label="Название машины" value="${esc(v.name)}" maxlength="500"><span>${currency('vehicles',v)}</span><label>Валюта бензина${currency('vehicles',v,'fuelCurrency')}</label><button class="danger" data-remove-car="${v.id}">Убрать машину</button></div><div class="fields">${labels.map(([f,l])=>input('vehicles',v.id,f,v[f],l)).join('')}</div><div class="vehicle-closed"><label><input type="checkbox" data-scope="vehicles" data-id="${v.id}" data-field="rentClosed" ${v.rentClosed?'checked':''}> Аренда закрыта</label><label><input type="checkbox" data-scope="vehicles" data-id="${v.id}" data-field="fuelClosed" ${v.fuelClosed?'checked':''}> Бензин закрыт</label></div><div class="vehicle-results" data-car-result="${v.id}"></div></div>`).join('');}
  function totals(){const c=M.compute(current),metric=(title,value,hint)=>`<div class="metric"><span>${title}</span><strong>${fmt(value)}</strong><small>${hint}</small></div>`;
    $('#totals').innerHTML=metric(c.unknown?'Известная часть плана':'План расходов',c.plan,current.settings.currency+' · вся группа')+metric(c.unknown?'Известная часть / гость':'Себестоимость / гость',c.perGuest,current.settings.currency+' · делим на '+current.settings.guests)+metric('Потрачено по факту',c.actual,c.actualCount+' из '+c.rows.length+' статей закрыто')+metric(c.forecastUnknown?'Известная часть прогноза':'Прогноз итоговых расходов',c.forecast,'факт закрытых + остаток незакрытых')+metric('Осталось по прогнозу',c.remaining,current.settings.currency+' · незакрытые статьи'+(c.forecastUnknown?' · сумма неполная':''))+metric('Деньги на руках',c.cash,'получено − потрачено, '+current.settings.currency)+metric('Прибыль по плану',c.profitPlan,'выручка − полный план, '+current.settings.currency)+metric('Прибыль по прогнозу',c.profitForecast,'выручка − прогноз, '+current.settings.currency);
    $('#missing').textContent=c.unknown?'Не хватает данных по '+c.unknown+' статьям: '+c.rows.filter(r=>r.plan===null).map(r=>r.name).join(', ')+'. Это частичная смета; прибыль не рассчитывается до заполнения плана.': 'План заполнен. Прогноз на гостя: '+fmt(c.forecastPerGuest)+' '+current.settings.currency+'. Выручка по заданной цене: '+fmt(c.revenue)+' '+current.settings.currency+'.';
    c.rows.forEach(r=>{const p=document.querySelector(`[data-plan="${r.id}"]`),d=document.querySelector(`[data-delta="${r.id}"]`),q=document.querySelector(`[data-quantity="${r.id}"]`);if(p)p.textContent=fmt(r.plan);if(d)d.textContent=r.delta===null?'—':(r.delta>0?'+':'')+fmt(r.delta);if(q)q.textContent='Всего: '+fmt(r.quantity);});
    current.vehicles.forEach(v=>{const rent=c.rows.find(r=>r.id===v.id+'-rent'),fuel=c.rows.find(r=>r.id===v.id+'-fuel');document.querySelector(`[data-car-result="${v.id}"]`).textContent='Аренда: '+fmt(rent.native)+' '+v.currency+' → '+fmt(rent.plan)+' '+current.settings.currency+'. Бензин: '+fmt(fuel.quantity)+' л → '+fmt(fuel.plan)+' '+current.settings.currency+'.';});portfolio();
  }
  function portfolio(){const docs=list.map(r=>r.id===current.id?current:r.document);if(!docs.some(b=>b.id===current.id))docs.push(current);const groups=M.portfolio(docs);$('#portfolio').innerHTML=Object.entries(groups).map(([currency,p])=>'<p><strong>'+currency+' · '+p.count+' проектов</strong> · выручка по ценам: '+fmt(p.revenue)+' · получено: '+fmt(p.received)+' · факт расходов: '+fmt(p.actual)+' · прогноз прибыли по заполненным: '+fmt(p.forecastProfit)+' · итоговая прибыль закрытых ('+p.completed+'): '+fmt(p.completedProfit)+(p.incomplete?' · неполных смет: '+p.incomplete:'')+'</p>').join('');}
  function menu(){const items=[...list];if(!items.some(x=>x.id===current.id))items.unshift({id:current.id,title:current.title+' · черновик'});$('#budgets').innerHTML=items.map(b=>`<option value="${b.id}" ${b.id===current.id?'selected':''}>${b.document?.settings.stage==='archived'?'[архив] ':''}${esc(b.title)}</option>`).join('');}
  function render(){ $('#title').value=current.title;$('#notes').value=current.notes;settings();lines();vehicles();totals();menu();}
  async function confirm(title,text){$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;const d=$('#confirm-dialog');d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true}));}
  function getError(e){return e?.message||'Онлайн-хранилище недоступно.';}
  async function loadList(){const {data,error}=await client.from('voyz_budgets').select('id,document,revision,updated_at').eq('owner_id',account).order('updated_at',{ascending:false}).limit(500);if(error)throw error;list=data.map(r=>({...r,title:r.document.title}));menu();}
  async function save(){clearTimeout(timer);if(!ready||saving||blocked)return false;if(!account){$('#login').showModal();return false;}if(!dirty&&revision>0)return true;let documentCopy;try{if(document.querySelector('input:invalid'))throw Error('Исправьте выделенное поле.');documentCopy=M.validate(current);}catch(e){notice(e.message);status('Проверьте поля');return false;}const owner=account,savedId=current.id,version=change,expected=revision;saving=true;status('Сохраняем онлайн…');$('#save').disabled=true;
    try{const {data,error}=await client.rpc('voyz_save_budget',{p_id:savedId,p_expected:expected,p_document:documentCopy});if(error)throw error;if(owner!==account)return false;revision=data.revision;if(change===version)dirty=false;cache();status(dirty?'Есть новые правки…':'Сохранено онлайн · '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}));notice('');const entry={id:savedId,title:documentCopy.title,document:documentCopy,revision,updated_at:data.updated_at};list=[entry,...list.filter(x=>x.id!==savedId)];menu();return true;
    }catch(e){if(owner!==account)return false;dirty=true;cache();if(/REVISION_CONFLICT/.test(getError(e))){blocked=true;notice('Эта смета изменена на другом устройстве. Ваш черновик сохранён здесь. Нажмите «Копия», чтобы сохранить его отдельно, либо скачайте JSON и нажмите «Обновить», чтобы получить онлайн-версию.');status('Конфликт · сохранение остановлено');}else{notice('Не сохранено онлайн: '+getError(e)+' Черновик на устройстве; повторите сохранение или скачайте JSON.');status('Не сохранено онлайн');}return false;
    }finally{saving=false;$('#save').disabled=false;if(dirty&&!blocked&&change!==version&&account)timer=setTimeout(save,900);}
  }
  async function leave(){if(saving){notice('Дождитесь завершения сохранения.');return false;}if(!dirty)return true;if(account&&!blocked&&await save())return true;return await confirm('Перейти к другой смете?','Есть несохранённые онлайн правки. Сначала скачайте JSON, если они нужны. Продолжение заменит аварийный черновик.');}
  async function pick(id){if(!await leave()){menu();return;}const row=list.find(r=>r.id===id);if(!row)return;current=M.validate(row.document);revision=row.revision;dirty=false;blocked=false;change++;cache();render();status('Загружено из онлайн-хранилища');notice('');}
  function download(content,type,name){const url=URL.createObjectURL(new Blob(['\ufeff'+content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  function copy(){if(saving)return notice('Дождитесь сохранения.');current=structuredClone(current);current.id=M.uid();current.title+=' · копия';revision=0;blocked=false;changed();render();}
  document.addEventListener('input',e=>{const el=e.target;if(el.id==='title'){current.title=el.value;changed();menu();return;}if(el.id==='notes'){current.notes=el.value;changed();return;}if(!el.dataset.scope)return;const {scope,id,field}=el.dataset;const row=scope==='settings'?current.settings:scope==='rates'?current.settings.rates:current[scope].find(r=>r.id===id);if(!row)return;let value=el.type==='checkbox'?el.checked:el.type==='number'?M.n(el.value):el.value;
    if(el.type==='number'&&value!==null&&(!Number.isFinite(value)||value<0||value>1e10)){el.setCustomValidity('Введите неотрицательное число');el.reportValidity();return;}
    if(scope==='settings'&&['guests','guides','days','nights'].includes(field)&&(!Number.isInteger(value)||value<(['guides','nights'].includes(field)?0:1)||value>(field==='guides'?50:['days','nights'].includes(field)?365:1000))){el.setCustomValidity('Введите допустимое целое число');el.reportValidity();return;}
    if(scope==='rates'&&value===0){el.setCustomValidity('Курс должен быть больше нуля');el.reportValidity();return;}
    el.setCustomValidity('');
    if(scope==='settings'&&field==='currency')return;
    try{if(scope==='settings'&&field==='guides'&&current.settings.autoCars)M.resize(current,'cars',value);if(scope==='settings'&&field==='nights')M.resize(current,'nights',value);}catch(err){el.value=row[field];notice(err.message);return;}
    row[field]=value;changed();if(scope==='settings'&&['guides','nights','days'].includes(field)||field==='unitsMode'){lines();vehicles();}totals();
  });
  document.addEventListener('change',e=>{const el=e.target;if(el.dataset.scope==='settings'&&el.dataset.field==='currency'){const code=el.value.toUpperCase();const hasMoney=current.lines.some(r=>r.actual!==null)||current.vehicles.some(r=>r.actualRent!==null||r.actualFuel!==null)||(current.settings.received??0)>0||current.settings.salePrice!==null;if(!/^[A-Z]{3}$/.test(code)||hasMoney){el.value=current.settings.currency;notice('Выберите валюту из трёх латинских букв до ввода факта, оплат и цены продажи. Для другой валюты создайте новую смету.');return;}const old=current.settings.currency;current.settings.currency=code;current.settings.rates=Object.fromEntries([...new Set([...Object.keys(current.settings.rates),old,...current.lines.map(r=>r.currency),...current.vehicles.flatMap(v=>[v.currency,v.fuelCurrency])])].filter(c=>c!==code).map(c=>[c,null]));changed();render();notice('Валюта учёта изменена. Введите курсы заново; цены расходов остались в своих исходных валютах.');}});
  $('#auto-cars').onchange=e=>{if(e.target.checked){try{M.resize(current,'cars',current.settings.guides);}catch(err){e.target.checked=false;notice(err.message);return;}}current.settings.autoCars=e.target.checked;changed();vehicles();totals();};
  $('#add-currency').onclick=()=>{const code=$('#new-currency').value.trim().toUpperCase();if(!/^[A-Z]{3}$/.test(code))return notice('Код валюты: три латинские буквы, например EUR.');if(Object.keys(current.settings.rates).length>=30)return notice('Максимум 30 курсов.');if(code!==current.settings.currency&&!Object.hasOwn(current.settings.rates,code))current.settings.rates[code]=null;$('#new-currency').value='';changed();settings();lines();vehicles();totals();};
  document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.close)$('#'+b.dataset.close).close();for(const [attr,collection] of [['removeLine','lines'],['removeCar','vehicles']])if(b.dataset[attr]){if(await confirm('Убрать расход?','Статья и её факт будут убраны из текущей сметы. Онлайн-история сохранений останется.')){current[collection]=current[collection].filter(r=>r.id!==b.dataset[attr]);if(collection==='vehicles')current.settings.autoCars=false;else current.settings.nights=current.lines.filter(r=>r.night).length;changed();render();}}});
  $('#save').onclick=save;$('#copy').onclick=copy;$('#budgets').onchange=e=>pick(e.target.value);
  $('#new').onclick=async()=>{if(!await leave())return;current=M.seed();current.title='Новый тур';current.lines=[];current.vehicles=[];current.notes='';current.settings.nights=0;current.settings.autoCars=false;current.settings.salePrice=null;current.settings.received=0;revision=0;blocked=false;changed();render();};
  $('#add-line').onclick=()=>{if(current.lines.length>=500)return notice('Максимум 500 статей.');current.lines.push({id:M.uid(),name:'Новый расход',category:'Прочее',basis:'fixed',units:1,price:null,currency:current.settings.currency,actual:null,note:'',extra:0,unitsMode:'fixed'});changed();lines();totals();};
  $('#add-car').onclick=()=>{if(current.vehicles.length>=50)return notice('Максимум 50 строк машин.');current.vehicles.push({id:M.uid(),name:'Машина '+(current.vehicles.length+1),count:1,days:current.settings.days,rent:null,currency:'USD',km:null,consumption:null,fuelPrice:null,fuelCurrency:current.settings.currency,actualRent:null,actualFuel:null});changed();vehicles();totals();};
  $('#export').onclick=()=>download(JSON.stringify(current,null,2),'application/json;charset=utf-8','VOYZ-смета.json');
  function exportExcel(all=false){
    const docs=all?[...list.filter(r=>r.id!==current.id).map(r=>r.document),current]:[current];const sheets=[];
    if(all){const groups=M.portfolio(docs);sheets.push({name:'Все проекты',rows:[['Проект','Валюта','Статус','Гостей','План (известно)','Факт расходов','Получено','Выручка по цене','Прогноз расходов','Прибыль по прогнозу','Неполных статей'],...docs.map(b=>{const c=M.compute(b);return [b.title,b.settings.currency,b.settings.stage,b.settings.guests,c.plan,c.actual,b.settings.received,c.revenue,c.forecast,c.profitForecast,c.unknown];}),[],['Итоги по валютам','Валюта','Выручка по цене','Получено','Факт расходов','Прогноз прибыли заполненных','Итоговая прибыль закрытых'],...Object.entries(groups).map(([code,p])=>['Итого',code,p.revenue,p.received,p.actual,p.forecastProfit,p.completedProfit])]});}
    else {const c=M.compute(current),base=current.settings.currency;sheets.push({name:'Смета',rows:[['VOYZ · '+current.title,'Валюта учёта: '+base],['Источник: данные организатора; экспорт — снимок на '+new Date().toLocaleString('ru-RU')],['Известный план',c.plan],['Неполных статей',c.unknown],['На гостя (известно)',c.perGuest],['Факт расходов',c.actual],['Прогноз (известно)',c.forecast],['Прибыль по прогнозу',c.profitForecast],[],['Статья','Категория','Количество всего','Сумма в исходной валюте','Валюта','План '+base,'Факт '+base,'Прогноз '+base,'Отклонение '+base,'Закрыта'],...c.rows.map(r=>[r.name,r.category,r.quantity,r.native,r.currency,r.plan,r.actual,r.forecast,r.delta,r.closed?'Да':'Нет']),[],['Примечание','Пустой факт не означает ноль. Прогноз = факт закрытых + максимум плана и факта открытых. Файл — снимок; онлайн-смета продолжает считаться в приложении.']]});
      sheets.push({name:'Параметры',rows:[['Параметр','Значение'],['Гостей',current.settings.guests],['Гидов',current.settings.guides],['Дней',current.settings.days],['Ночей',current.settings.nights],['Валюта учёта',base],['Цена продажи за гостя',current.settings.salePrice],['Получено',current.settings.received],...Object.entries(current.settings.rates).map(([code,rate])=>['Курс: 1 '+code+' в '+base,rate]),[],['Статья','Примечание','Цена','Валюта','Кого считаем','Дополнительно','Единиц','Множитель'],...current.lines.map(r=>[r.name,r.note,r.price,r.currency,r.basis,r.extra,r.units,r.unitsMode]),[],['Авто','Количество','Дней','Аренда / день','Валюта аренды','Пробег / авто','Л / 100 км','Цена бензина / л','Валюта бензина'],...current.vehicles.map(v=>[v.name,v.count,v.days,v.rent,v.currency,v.km,v.consumption,v.fuelPrice,v.fuelCurrency]),[],['Заметки',current.notes]]});}
    const blob=window.VoyzBudgetXlsx(sheets),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=all?'VOYZ-все-проекты.xlsx':'VOYZ-смета.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);
  }
  $('#csv').onclick=()=>exportExcel(false);$('#excel-all').onclick=()=>exportExcel(true);
  $('#import').onclick=()=>{$('#import-file').value='';$('#import-file').click();};$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('Максимум 2 МБ.');const b=M.validate(JSON.parse((await f.text()).replace(/^\uFEFF/,'')));if(!await leave())return;current=b;current.id=M.uid();revision=0;blocked=false;changed();render();}catch(e){notice('Импорт не выполнен: '+getError(e));}};
  $('#refresh').onclick=async()=>{if(!account)return $('#login').showModal();if(!await leave())return;try{await loadList();const row=list.find(r=>r.id===current.id);if(row){current=M.validate(row.document);revision=row.revision;dirty=false;blocked=false;cache();render();status('Загружено онлайн');notice('');}else notice('Этой сметы ещё нет онлайн. Нажмите «Сохранить онлайн».');}catch(e){notice(getError(e));}};
  $('#history').onclick=async()=>{if(!account)return $('#login').showModal();$('#history-dialog').showModal();$('#versions').textContent='Загружаем…';try{const {data,error}=await client.from('voyz_budget_versions').select('revision,document,saved_at').eq('owner_id',account).eq('budget_id',current.id).order('revision',{ascending:false}).limit(50);if(error)throw error;$('#versions').replaceChildren();if(!data.length)$('#versions').textContent='Пока нет онлайн-сохранений.';data.forEach(v=>{const b=document.createElement('button');b.textContent='Версия '+v.revision+' · '+new Date(v.saved_at).toLocaleString('ru-RU');b.onclick=async()=>{if(!await leave())return;current=M.validate(v.document);current.id=M.uid();current.title+=' · версия '+v.revision;revision=0;blocked=false;changed();render();$('#history-dialog').close();};$('#versions').append(b);});}catch(e){$('#versions').textContent=getError(e);}};
  $('#auth').onclick=async()=>{if(!account){$('#login').showModal();return;}if(saving)return notice('Дождитесь сохранения.');if(!await leave())return;await window.VoyzCloud.signOut();};
  $('#login-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;try{const {error}=await client.auth.signInWithOtp({email:$('#email').value,options:{shouldCreateUser:false,emailRedirectTo:window.VOYZ_CLOUD.publicUrl}});if(error)throw error;$('#login-status').textContent='Письмо отправлено. Откройте ссылку, затем нажмите «Сметы» на доске.';}catch(e){$('#login-status').textContent=getError(e);}finally{submit.disabled=false;}};
  window.addEventListener('online',()=>{if(account&&dirty&&!blocked)save();});window.addEventListener('beforeunload',e=>{if(dirty||saving){cache();e.preventDefault();e.returnValue='';}});
  async function authChanged(session){const next=session?.user?.id||null;if(ready&&next===account)return;if(ready&&saving){notice('Аккаунт изменён во время сохранения. Текущий черновик сохранён на устройстве; обновите страницу.');blocked=true;return;}const previous=account;if(ready)cache();account=next;client=window.VoyzCloud.init();list=[];revision=0;blocked=false;change++;dirty=false;$('#auth').textContent=account?'Выйти':'Войти';
    const recovered=restoreCache();if(!recovered){current=M.seed();dirty=false;}ready=true;
    if(account){try{await loadList();if(recovered&&dirty){notice('Восстановлен несохранённый черновик этого аккаунта. Нажмите «Сохранить онлайн».');status('Черновик восстановлен');}else if(list.length){const r=list.find(r=>r.id===current.id)||list[0];current=M.validate(r.document);revision=r.revision;status('Загружено онлайн');}else{revision=0;notice('Сохраните первую смету онлайн. Черновики без входа можно перенести через JSON.');status('Новая смета · ещё не сохранена онлайн');}}catch(e){notice('Не удалось получить сметы: '+getError(e)+' Сохранение онлайн пока не подтверждено.');status('Онлайн недоступен');}}
    else{notice('Войдите, чтобы сметы сохранялись онлайн и открывались на других устройствах. Пока это черновик на этом устройстве.');status('Черновик · нет онлайн-сохранения');}cache();render();
    if(account&&!dirty){try{const guest=JSON.parse(localStorage.getItem('voyz-budget-draft.v1.guest'));if(guest?.dirty){const candidate=M.validate(guest.document);notice('Есть черновик, созданный до входа. Можно перенести его отдельной сметой.');const transfer=document.createElement('button');transfer.textContent='Перенести черновик';transfer.onclick=async()=>{if(!await leave())return;current=candidate;current.id=M.uid();revision=0;blocked=false;changed();render();notice('Черновик перенесён. Сохраняем онлайн…');guest.dirty=false;localStorage.setItem('voyz-budget-draft.v1.guest',JSON.stringify(guest));};$('#notice').append(' ',transfer);}}catch{}}
  }
  try{client=window.VoyzCloud.init();window.VoyzCloud.onAuth(authChanged);window.VoyzCloud.session().then(authChanged).catch(e=>{notice(getError(e));authChanged(null);});}catch(e){ready=true;restoreCache();render();status('Онлайн недоступен');notice(getError(e));}
})();
